import{_ as e,c as r,o,a2 as i}from"./chunks/framework.CIiVzG-O.js";const p=JSON.parse('{"title":"Guía de uso","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/usage.md","filePath":"es/guide/usage.md","lastUpdated":1793163976000}'),n={name:"es/guide/usage.md"};function t(l,a,s,c,d,h){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="guia-de-uso" tabindex="-1">Guía de uso <a class="header-anchor" href="#guia-de-uso" aria-label="Permalink to &quot;Guía de uso&quot;">​</a></h1><h2 id="apertura-de-archivos" tabindex="-1">Apertura de archivos <a class="header-anchor" href="#apertura-de-archivos" aria-label="Permalink to &quot;Apertura de archivos&quot;">​</a></h2><h3 id="doble-clic-para-abrir" tabindex="-1">Doble clic para abrir <a class="header-anchor" href="#doble-clic-para-abrir" aria-label="Permalink to &quot;Doble clic para abrir&quot;">​</a></h3><p>NueZip se registra como el manejador predeterminado para todos los formatos de archivo compatibles. Simplemente haz doble clic en cualquier archivo comprimido (<code>.zip</code>, <code>.rar</code>, <code>.7z</code>, <code>.tar</code>, <code>.gz</code>, <code>.bz2</code>, <code>.xz</code>, <code>.zst</code>) para abrirlo en la ventana principal de NueZip.</p><h3 id="abrir-con-nuezip-menu-contextual-de-finder" tabindex="-1">Abrir con NueZip (menú contextual de Finder) <a class="header-anchor" href="#abrir-con-nuezip-menu-contextual-de-finder" aria-label="Permalink to &quot;Abrir con NueZip (menú contextual de Finder)&quot;">​</a></h3><p>Haz clic derecho en cualquier archivo comprimido y selecciona <strong>Abrir con NueZip</strong> en el menú contextual. La extensión de Finder también ofrece acciones rápidas:</p><ul><li><strong>Extraer aquí</strong> — Extrae el contenido del archivo a la carpeta actual</li><li><strong>Extraer a &quot;NombreCarpeta/&quot;</strong> — Extrae a una subcarpeta con nombre</li><li><strong>Comprimir a ZIP</strong> — Comprime los archivos/carpetas seleccionados a un archivo ZIP</li><li><strong>Abrir con NueZip</strong> — Abre en la ventana principal del explorador</li></ul><h3 id="arrastrar-y-soltar-en-la-bandeja" tabindex="-1">Arrastrar y soltar en la bandeja <a class="header-anchor" href="#arrastrar-y-soltar-en-la-bandeja" aria-label="Permalink to &quot;Arrastrar y soltar en la bandeja&quot;">​</a></h3><p>Arrastra cualquier archivo comprimido sobre el icono de la barra de menú de NueZip para abrirlo rápidamente en el panel de desecho y acceder al instante. También puedes arrastrar archivos sobre el icono de la bandeja para comprimirlos.</p><h2 id="extraccion-de-archivos" tabindex="-1">Extracción de archivos <a class="header-anchor" href="#extraccion-de-archivos" aria-label="Permalink to &quot;Extracción de archivos&quot;">​</a></h2><h3 id="extraccion-basica" tabindex="-1">Extracción básica <a class="header-anchor" href="#extraccion-basica" aria-label="Permalink to &quot;Extracción básica&quot;">​</a></h3><ol><li>Abre un archivo en NueZip</li><li>Haz clic en el botón <strong>Extraer</strong> de la barra de herramientas</li><li>Elige una carpeta de destino</li><li>Haz clic en <strong>Extraer</strong></li></ol><h3 id="extraccion-rapida-desde-finder" tabindex="-1">Extracción rápida desde Finder <a class="header-anchor" href="#extraccion-rapida-desde-finder" aria-label="Permalink to &quot;Extracción rápida desde Finder&quot;">​</a></h3><p>Haz clic derecho en un archivo en Finder y selecciona una de las acciones rápidas:</p><ul><li><strong>Extraer aquí</strong> — Extrae directamente a la carpeta actual</li><li><strong>Extraer a &quot;[NombreArchivo]/&quot;</strong> — Extrae a una subcarpeta con nombre para una organización limpia</li></ul><h3 id="extraer-con-contrasena" tabindex="-1">Extraer con contraseña <a class="header-anchor" href="#extraer-con-contrasena" aria-label="Permalink to &quot;Extraer con contraseña&quot;">​</a></h3><p>Para archivos protegidos con contraseña, NueZip solicitará la contraseña. El gestor de contraseñas integrado puede almacenar las credenciales de forma segura en tu cadena de claves local para uso futuro.</p><h2 id="compresion-de-archivos" tabindex="-1">Compresión de archivos <a class="header-anchor" href="#compresion-de-archivos" aria-label="Permalink to &quot;Compresión de archivos&quot;">​</a></h2><h3 id="crear-un-nuevo-archivo" tabindex="-1">Crear un nuevo archivo <a class="header-anchor" href="#crear-un-nuevo-archivo" aria-label="Permalink to &quot;Crear un nuevo archivo&quot;">​</a></h3><ol><li>Selecciona archivos o carpetas en la ventana principal de NueZip</li><li>Haz clic en el botón <strong>Comprimir</strong> de la barra de herramientas</li><li>Elige el formato de archivo (ZIP, 7z, TAR, GZIP, etc.)</li><li>Configura los ajustes de compresión (nivel, método de cifrado)</li><li>Haz clic en <strong>Comprimir</strong></li></ol><h3 id="comprimir-desde-finder" tabindex="-1">Comprimir desde Finder <a class="header-anchor" href="#comprimir-desde-finder" aria-label="Permalink to &quot;Comprimir desde Finder&quot;">​</a></h3><p>Haz clic derecho en archivos/carpetas en Finder y selecciona <strong>Comprimir con NueZip</strong>:</p><ul><li><strong>Comprimir a ZIP</strong> — Creación rápida de un archivo ZIP</li><li><strong>Comprimir con opciones</strong> — Abre NueZip con ajustes avanzados</li></ul><h3 id="comprimir-mediante-arrastrar-y-soltar" tabindex="-1">Comprimir mediante arrastrar y soltar <a class="header-anchor" href="#comprimir-mediante-arrastrar-y-soltar" aria-label="Permalink to &quot;Comprimir mediante arrastrar y soltar&quot;">​</a></h3><p>Arrastra archivos sobre el icono de la bandeja de la barra de menú de NueZip para crear rápidamente un archivo ZIP.</p><h2 id="operaciones-por-lotes" tabindex="-1">Operaciones por lotes <a class="header-anchor" href="#operaciones-por-lotes" aria-label="Permalink to &quot;Operaciones por lotes&quot;">​</a></h2><h3 id="compresion-por-lotes" tabindex="-1">Compresión por lotes <a class="header-anchor" href="#compresion-por-lotes" aria-label="Permalink to &quot;Compresión por lotes&quot;">​</a></h3><ol><li>Selecciona varios elementos en NueZip</li><li>Elige <strong>Compresión por lotes</strong> desde la barra de herramientas o el menú Archivo</li><li>Cada elemento se comprimirá en un archivo separado</li></ol><h3 id="extraccion-por-lotes" tabindex="-1">Extracción por lotes <a class="header-anchor" href="#extraccion-por-lotes" aria-label="Permalink to &quot;Extracción por lotes&quot;">​</a></h3><ol><li>Selecciona varios archivos en NueZip</li><li>Elige <strong>Extracción por lotes</strong> desde la barra de herramientas o el menú Archivo</li><li>Todos los archivos se extraerán simultáneamente</li></ol><h3 id="conversion-por-lotes" tabindex="-1">Conversión por lotes <a class="header-anchor" href="#conversion-por-lotes" aria-label="Permalink to &quot;Conversión por lotes&quot;">​</a></h3><ol><li>Selecciona uno o más archivos</li><li>Elige <strong>Convertir</strong> → selecciona el formato de destino</li><li>NueZip recomprimirá cada archivo en el formato elegido</li></ol><h3 id="cifrado-por-lotes" tabindex="-1">Cifrado por lotes <a class="header-anchor" href="#cifrado-por-lotes" aria-label="Permalink to &quot;Cifrado por lotes&quot;">​</a></h3><ol><li>Selecciona varios archivos ZIP</li><li>Elige <strong>Cifrado por lotes</strong></li><li>Establece una contraseña — todos los archivos seleccionados estarán protegidos con contraseña</li></ol><h2 id="conversion-de-formato" tabindex="-1">Conversión de formato <a class="header-anchor" href="#conversion-de-formato" aria-label="Permalink to &quot;Conversión de formato&quot;">​</a></h2><p>Convierte archivos entre cualquiera de los formatos compatibles:</p><ol><li>Abre un archivo</li><li>Haz clic en <strong>Convertir</strong> en la barra de herramientas</li><li>Selecciona el formato de destino (por ejemplo, RAR → ZIP, 7z → TAR.GZ)</li><li>Elige la ubicación de salida</li><li>Haz clic en <strong>Convertir</strong></li></ol><h2 id="reparacion-de-archivos" tabindex="-1">Reparación de archivos <a class="header-anchor" href="#reparacion-de-archivos" aria-label="Permalink to &quot;Reparación de archivos&quot;">​</a></h2><p>Para archivos RAR o ZIP corruptos:</p><ol><li>Abre el archivo corrupto</li><li>Haz clic en <strong>Reparar</strong> en la barra de herramientas</li><li>NueZip intentará reconstruir los datos del archivo</li><li>El archivo reparado se guarda como un nuevo archivo</li></ol><h2 id="busqueda-en-archivos" tabindex="-1">Búsqueda en archivos <a class="header-anchor" href="#busqueda-en-archivos" aria-label="Permalink to &quot;Búsqueda en archivos&quot;">​</a></h2><p>Encuentra archivos específicos dentro de los archivos:</p><ol><li>Haz clic en el botón <strong>Buscar</strong> en la barra de herramientas</li><li>Introduce un patrón de nombre de archivo</li><li>NueZip busca en todas las entradas del archivo abierto</li><li>Los resultados se muestran con rutas completas para una navegación rápida</li></ol><h2 id="prueba-de-rendimiento" tabindex="-1">Prueba de rendimiento <a class="header-anchor" href="#prueba-de-rendimiento" aria-label="Permalink to &quot;Prueba de rendimiento&quot;">​</a></h2><p>Prueba el rendimiento de compresión de tu sistema:</p><ol><li>Ve a <strong>Herramientas → Prueba de rendimiento</strong></li><li>NueZip ejecuta pruebas de compresión usando varios formatos y ajustes</li><li>Los resultados muestran la velocidad de compresión (MB/s) y la relación para cada formato</li><li>Úsalo para comparar el rendimiento entre diferentes métodos de compresión</li></ol><h2 id="archivos-multi-volumen-divididos" tabindex="-1">Archivos multi-volumen (divididos) <a class="header-anchor" href="#archivos-multi-volumen-divididos" aria-label="Permalink to &quot;Archivos multi-volumen (divididos)&quot;">​</a></h2><p>Crea archivos divididos para datos grandes:</p><ol><li>Durante la compresión, activa <strong>Dividir en volúmenes</strong></li><li>Elige el tamaño del volumen (por ejemplo, 100 MB, 650 MB, 4,7 GB, o personalizado)</li><li>NueZip crea archivos de partes numerados (<code>.zip.001</code>, <code>.zip.002</code>, etc.)</li><li>Para extraer, abre el primer archivo de parte — NueZip carga automáticamente el resto</li></ol><ul><li><strong>Contraseña</strong>: Proporciona una contraseña para archivos cifrados</li><li><strong>Envolver en carpeta</strong>: Crea automáticamente una carpeta raíz si el archivo no tiene un único directorio raíz</li><li><strong>Abrir después</strong>: Muestra los archivos extraídos en Finder al finalizar</li><li><strong>Conservar archivos dañados</strong>: Preserva cualquier archivo extraído antes de un error (para recuperación parcial)</li><li><strong>Modo de actualización</strong>: Elige cómo manejar los archivos existentes (sobrescribir, omitir, renombrar)</li></ul><h3 id="extraccion-por-lotes-1" tabindex="-1">Extracción por lotes <a class="header-anchor" href="#extraccion-por-lotes-1" aria-label="Permalink to &quot;Extracción por lotes&quot;">​</a></h3><ol><li>Ve a <strong>Herramientas → Extracción por lotes</strong></li><li>Haz clic en <strong>Añadir archivos...</strong> para seleccionar archivos comprimidos</li><li>Elige una carpeta de destino</li><li>Opcionalmente activa <strong>Eliminar archivos de origen tras la extracción</strong></li><li>Haz clic en <strong>Iniciar</strong></li></ol><h2 id="creacion-de-archivos" tabindex="-1">Creación de archivos <a class="header-anchor" href="#creacion-de-archivos" aria-label="Permalink to &quot;Creación de archivos&quot;">​</a></h2><h3 id="comprimir-archivos" tabindex="-1">Comprimir archivos <a class="header-anchor" href="#comprimir-archivos" aria-label="Permalink to &quot;Comprimir archivos&quot;">​</a></h3><ol><li>Haz clic en el botón <strong>Comprimir</strong> de la barra de herramientas</li><li>Selecciona los archivos a comprimir (o arrástralos y suéltalos en la ventana)</li><li>Elige el <strong>formato de archivo</strong>: ZIP, 7Z, TAR, GZIP, BZIP2</li><li>Configura el <strong>método de compresión</strong> y el nivel</li><li>Establece la <strong>ubicación de guardado</strong> y el nombre del archivo</li><li>Opcionalmente establece una <strong>contraseña</strong> para el cifrado</li><li>Opcionalmente establece el <strong>tamaño de división</strong> para archivos multi-volumen</li><li>Haz clic en <strong>Comprimir</strong></li></ol><h3 id="anadir-archivos-a-un-archivo-existente" tabindex="-1">Añadir archivos a un archivo existente <a class="header-anchor" href="#anadir-archivos-a-un-archivo-existente" aria-label="Permalink to &quot;Añadir archivos a un archivo existente&quot;">​</a></h3><ol><li>Abre un archivo existente en NueZip</li><li>Haz clic en <strong>Añadir archivos</strong> en la barra de herramientas</li><li>Selecciona los archivos a añadir</li><li>Haz clic en <strong>Añadir</strong></li></ol><h2 id="operaciones-por-lotes-1" tabindex="-1">Operaciones por lotes <a class="header-anchor" href="#operaciones-por-lotes-1" aria-label="Permalink to &quot;Operaciones por lotes&quot;">​</a></h2><h3 id="compresion-por-lotes-1" tabindex="-1">Compresión por lotes <a class="header-anchor" href="#compresion-por-lotes-1" aria-label="Permalink to &quot;Compresión por lotes&quot;">​</a></h3><ol><li>Ve a <strong>Herramientas → Compresión por lotes</strong></li><li>Haz clic en <strong>Seleccionar archivos/carpetas...</strong> para elegir elementos</li><li>Cada elemento seleccionado se convertirá en un archivo separado</li><li>Configura el <strong>formato</strong>, la <strong>ubicación de guardado</strong> y el prefijo de nombre de archivo</li><li>Haz clic en <strong>Iniciar</strong></li></ol><h3 id="conversion-de-formato-por-lotes" tabindex="-1">Conversión de formato por lotes <a class="header-anchor" href="#conversion-de-formato-por-lotes" aria-label="Permalink to &quot;Conversión de formato por lotes&quot;">​</a></h3><ol><li>Ve a <strong>Herramientas → Conversión de formato por lotes</strong></li><li>Haz clic en <strong>Añadir archivos...</strong> para seleccionar archivos de origen</li><li>Elige el <strong>formato de destino</strong></li><li>Opcionalmente activa <strong>Eliminar archivos de origen tras la conversión</strong></li><li>Haz clic en <strong>Iniciar</strong></li></ol><h3 id="cifrado-por-lotes-1" tabindex="-1">Cifrado por lotes <a class="header-anchor" href="#cifrado-por-lotes-1" aria-label="Permalink to &quot;Cifrado por lotes&quot;">​</a></h3><ol><li>Ve a <strong>Herramientas → Cifrado por lotes</strong></li><li>Haz clic en <strong>Añadir archivos...</strong> para seleccionar archivos</li><li>Introduce una <strong>contraseña</strong></li><li>Haz clic en <strong>Cifrar</strong></li></ol><h2 id="funciones-avanzadas" tabindex="-1">Funciones avanzadas <a class="header-anchor" href="#funciones-avanzadas" aria-label="Permalink to &quot;Funciones avanzadas&quot;">​</a></h2><h3 id="reparacion-de-archivos-1" tabindex="-1">Reparación de archivos <a class="header-anchor" href="#reparacion-de-archivos-1" aria-label="Permalink to &quot;Reparación de archivos&quot;">​</a></h3><p>Repara archivos corruptos o dañados:</p><ol><li>Selecciona el archivo dañado</li><li>Ve a <strong>Herramientas → Reparar archivo</strong></li><li>NueZip escaneará la cabecera, reconstruirá el directorio y corregirá los bloques de datos</li><li>Revisa el resultado de la reparación</li></ol><h3 id="conversion-de-formato-1" tabindex="-1">Conversión de formato <a class="header-anchor" href="#conversion-de-formato-1" aria-label="Permalink to &quot;Conversión de formato&quot;">​</a></h3><p>Convierte archivos entre formatos:</p><ol><li>Abre un archivo o selecciona un archivo</li><li>Ve a <strong>Archivo → Convertir formato</strong></li><li>Elige el formato de destino y el nivel de compresión</li><li>Opcionalmente elimina el archivo original</li><li>Haz clic en <strong>Convertir</strong></li></ol><h3 id="gestor-de-contrasenas" tabindex="-1">Gestor de contraseñas <a class="header-anchor" href="#gestor-de-contrasenas" aria-label="Permalink to &quot;Gestor de contraseñas&quot;">​</a></h3><p>NueZip almacena de forma segura las contraseñas de archivos en tu cadena de claves local:</p><ol><li>Ve a <strong>Herramientas → Gestor de contraseñas</strong></li><li>Consulta todas las contraseñas guardadas</li><li>Añade, edita o elimina entradas</li><li>Las contraseñas se aplican automáticamente al abrir archivos cifrados coincidentes</li></ol><h3 id="prueba-de-rendimiento-1" tabindex="-1">Prueba de rendimiento <a class="header-anchor" href="#prueba-de-rendimiento-1" aria-label="Permalink to &quot;Prueba de rendimiento&quot;">​</a></h3><p>Prueba el rendimiento de compresión de tu sistema:</p><ol><li>Ve a <strong>Herramientas → Prueba de rendimiento</strong></li><li>Selecciona un archivo de prueba (o usa el predeterminado)</li><li>Haz clic en <strong>Probar</strong></li><li>Consulta los resultados, incluyendo velocidad de compresión/descompresión y calificación</li></ol><h3 id="busqueda-en-archivos-1" tabindex="-1">Búsqueda en archivos <a class="header-anchor" href="#busqueda-en-archivos-1" aria-label="Permalink to &quot;Búsqueda en archivos&quot;">​</a></h3><p>Encuentra archivos dentro de los archivos:</p><ol><li>Abre un archivo</li><li>Pulsa <code>Cmd+F</code> o haz clic en el icono de búsqueda</li><li>Introduce un nombre de archivo, opcionalmente coincidiendo mayúsculas o palabra completa</li><li>Explora los resultados de búsqueda y haz clic para navegar</li></ol><h2 id="atajos-de-teclado" tabindex="-1">Atajos de teclado <a class="header-anchor" href="#atajos-de-teclado" aria-label="Permalink to &quot;Atajos de teclado&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Atajo</th><th>Acción</th></tr></thead><tbody><tr><td><code>Cmd+O</code></td><td>Abrir archivo</td></tr><tr><td><code>Cmd+N</code></td><td>Nuevo archivo</td></tr><tr><td><code>Cmd+E</code></td><td>Extraer</td></tr><tr><td><code>Cmd+F</code></td><td>Buscar en el archivo</td></tr><tr><td><code>Cmd+,</code></td><td>Abrir ajustes</td></tr><tr><td><code>Cmd+W</code></td><td>Cerrar ventana</td></tr><tr><td><code>Cmd+Q</code></td><td>Salir de la aplicación</td></tr><tr><td><code>Cmd+↑</code></td><td>Subir un nivel</td></tr><tr><td><code>Cmd+→</code></td><td>Avanzar</td></tr></tbody></table><h2 id="ajustes" tabindex="-1">Ajustes <a class="header-anchor" href="#ajustes" aria-label="Permalink to &quot;Ajustes&quot;">​</a></h2><p>Accede a los ajustes a través de <strong>NueZip → Ajustes</strong> o pulsa <code>Cmd+,</code>:</p><ul><li><strong>General</strong>: Idioma, iniciar al iniciar sesión, tema de apariencia</li><li><strong>Compresión</strong>: Formato predeterminado, nivel de compresión, tamaño de división</li><li><strong>Extracción</strong>: Destino predeterminado, comportamiento de envoltura, resolución de conflictos</li><li><strong>Acceso a carpetas</strong>: Gestiona los permisos de carpetas y los marcadores</li><li><strong>Avanzado</strong>: Aceleración por hardware, número de hilos, directorio temporal</li><li><strong>Privacidad</strong>: Preferencias de recopilación de datos</li></ul>',85)])])}const m=e(n,[["render",t]]);export{p as __pageData,m as default};
